import {
  ChangeDetectionStrategy, Component, DestroyRef, ElementRef, ViewEncapsulation,
  computed, effect, inject, input, model, output, signal, viewChild,
} from '@angular/core';
import { HrmEmpty } from 'hrm-ui';

/**
 * @file Form Design System — TRAIT `conflict` + TRAIT `unsaved-guard`.
 *
 * Bổ sung cho `_form-ds.ts` (cùng thư mục) hai mảnh còn thiếu của shell form nghiệp vụ:
 *   - `vnr-conflict-panel`  — BẢNG cảnh báo xung đột nghiệp vụ (trùng lịch, trùng ngày
 *                             hiệu lực, vượt hạn mức, thiếu điều kiện…).
 *   - `vnr-unsaved-guard`   — CHẶN rời form khi còn thay đổi chưa lưu (dải nhắc + hộp
 *                             thoại xác nhận + chặn đóng tab của trình duyệt).
 *
 * RANH GIỚI CHUNG (thực thi bằng THIẾT KẾ, không bằng lời nhắc): cả hai component đều
 * KHÔNG chứa nghiệp vụ. Chúng không tự phát hiện xung đột và không tự tính form có dirty
 * hay không — domain service / form state tính sẵn rồi truyền vào. Nhờ vậy dùng lại được
 * cho nghỉ phép · công tác · đăng ký ca · điều chuyển · tăng lương · đào tạo…
 *
 * File này là ỨNG VIÊN để chuyển lên `libs/hrm-ui` sau khi nghiệm thu trên template.
 */

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · conflict — cảnh báo xung đột nghiệp vụ
// ══════════════════════════════════════════════════════════════════════════════

/**
 * Mức nghiêm trọng của một xung đột.
 * - `error` — CHẶN gửi/lưu (vd: trùng ngày hiệu lực, vượt hạn mức cứng).
 * - `warn`  — cho gửi nhưng cần cân nhắc (vd: trùng lịch với đồng nghiệp cùng nhóm).
 * - `info`  — thông tin ngữ cảnh, không cản trở (vd: rơi vào tuần cao điểm).
 */
export type VnrConflictLevel = 'info' | 'warn' | 'error';

/** Một dòng xung đột do tầng nghiệp vụ sinh ra — UI chỉ hiển thị, không suy diễn thêm. */
export interface VnrConflictItem {
  readonly id: string;
  readonly level: VnrConflictLevel;
  /** Câu tóm tắt xung đột, vd "Trùng lịch nghỉ với Nguyễn Văn A". */
  readonly title: string;
  /** Diễn giải chi tiết (khoảng ngày, số dư còn lại, điều kiện thiếu…). */
  readonly detail?: string | null;
  /** Nguồn phát hiện, vd "Lịch nghỉ phép", "Chính sách công tác phí". */
  readonly source?: string | null;
  /** true ⇒ hiện nút hành động để người dùng tự xử lý. */
  readonly resolvable?: boolean;
  /** Nhãn nút xử lý, vd "Chọn ngày khác", "Xin duyệt ngoại lệ". */
  readonly actionLabel?: string | null;
}

/** Nhóm xung đột theo mức — do panel tự gom, KHÔNG phải input. */
export interface VnrConflictGroup {
  readonly level: VnrConflictLevel;
  readonly label: string;
  readonly items: readonly VnrConflictItem[];
}

/** Thứ tự đọc: nặng nhất lên trước — mắt gặp `error` trước khi gặp `info`. */
const VNR_CONFLICT_ORDER: readonly VnrConflictLevel[] = ['error', 'warn', 'info'];

/** Nhãn tiếng Việt của từng mức — dùng cho CẢ chip lẫn tiêu đề nhóm. */
const VNR_CONFLICT_LABEL: Record<VnrConflictLevel, string> = {
  error: 'Lỗi',
  warn: 'Cảnh báo',
  info: 'Thông tin',
};

/** Danh từ đếm trong tiêu đề, vd "2 lỗi · 1 cảnh báo". */
const VNR_CONFLICT_NOUN: Record<VnrConflictLevel, string> = {
  error: 'lỗi',
  warn: 'cảnh báo',
  info: 'thông tin',
};

/**
 * Bảng cảnh báo XUNG ĐỘT nghiệp vụ.
 *
 * RANH GIỚI: component KHÔNG dò trùng lịch, KHÔNG so ngày hiệu lực, KHÔNG tính hạn mức.
 * Nó nhận danh sách đã phát hiện và chỉ lo phần trình bày: gom nhóm theo mức, đếm ở tiêu đề,
 * làm nổi bật mức `error`, và bắn `resolve` / `inspect` để caller xử lý tiếp.
 *
 * KHẢ NĂNG ĐỌC: mỗi mục LUÔN có chip CHỮ ("Lỗi" / "Cảnh báo" / "Thông tin") bên cạnh màu —
 * người mù màu vẫn phân biệt được mức độ mà không cần nhìn nền.
 */
@Component({
  selector: 'vnr-conflict-panel',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [HrmEmpty],
  template: `
    <section class="vnr-cp" [attr.data-top]="topLevel()" [class.is-collapsed]="collapsed()">
      <header class="vnr-cp__hd">
        <button type="button" class="vnr-cp__tg" [attr.aria-expanded]="!collapsed()" (click)="toggle()">
          <span class="cv" aria-hidden="true">{{ collapsed() ? '▸' : '▾' }}</span>
          <span class="t">{{ title() }}</span>
          @if (countLabel()) {
            <span class="c">{{ countLabel() }}</span>
          } @else {
            <span class="c is-ok">Không có xung đột</span>
          }
          <span class="sp"></span>
          <span class="ac">{{ collapsed() ? 'Mở rộng' : 'Thu gọn' }}</span>
        </button>
      </header>

      @if (!collapsed()) {
        <div class="vnr-cp__bd">
          @for (g of groups(); track g.level) {
            <div class="vnr-cp__gr" [attr.data-lv]="g.level">
              <div class="vnr-cp__gh">
                <span class="lv">{{ g.label }}</span>
                <span class="n">{{ g.items.length }} mục</span>
              </div>

              @for (c of g.items; track c.id) {
                <article class="vnr-cp__it" [attr.data-lv]="c.level">
                  <div class="hd">
                    <!-- Chip CHỮ: mức độ đọc được không phụ thuộc màu -->
                    <span class="tag">{{ g.label }}</span>
                    <span class="ti">{{ c.title }}</span>
                  </div>
                  @if (c.detail) { <p class="de">{{ c.detail }}</p> }
                  <div class="ft">
                    @if (c.source) { <span class="sr">Nguồn: {{ c.source }}</span> }
                    <span class="sp"></span>
                    <button type="button" class="vnr-cp__b" (click)="inspect.emit(c.id)">Xem chi tiết</button>
                    @if (c.resolvable) {
                      <button type="button" class="vnr-cp__b is-primary" (click)="resolve.emit(c.id)">
                        {{ c.actionLabel || 'Xử lý' }}
                      </button>
                    }
                  </div>
                </article>
              }
            </div>
          } @empty {
            <!-- Rỗng cấp PANEL: cả vùng bảng xung đột trống ⇒ dùng trạng thái rỗng của DS -->
            <hrm-empty preset="no-data" description="Không phát hiện xung đột nào với dữ liệu hiện tại." />
          }
        </div>
      }
    </section>
  `,
  styles: [`
    /* Panel là GRID ITEM khi đặt trong .vnr-fg ⇒ quy tắc phải nhắm PHẦN TỬ HOST,
       không phải div bên trong. Đặt grid-column lên .vnr-cp sẽ không có tác dụng. */
    vnr-conflict-panel { display: block; min-inline-size: 0; }
    .vnr-fg > vnr-conflict-panel { grid-column: 1 / -1; }

    .vnr-cp { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); overflow: hidden; }
    .vnr-cp[data-top='error'] { border-color: var(--error-base); }
    .vnr-cp[data-top='warn']  { border-color: var(--warning-border); }

    .vnr-cp__hd { border-block-end: 1px solid var(--border-soft); }
    .vnr-cp.is-collapsed .vnr-cp__hd { border-block-end: none; }
    .vnr-cp__tg { inline-size: 100%; display: flex; align-items: center; gap: var(--space-2, 8px);
      padding: var(--space-2-5, 10px) var(--space-3, 12px); border: none; background: var(--bg-surface-subtle);
      font: inherit; color: var(--text-strong); text-align: start; cursor: pointer; }
    .vnr-cp[data-top='error'] .vnr-cp__tg { background: var(--error-bg); }
    .vnr-cp[data-top='warn']  .vnr-cp__tg { background: var(--warning-bg); }
    .vnr-cp[data-top='info']  .vnr-cp__tg { background: var(--info-bg); }
    .vnr-cp__tg:focus-visible { outline: 2px solid var(--primary-base); outline-offset: -2px; }
    .vnr-cp__tg .cv { inline-size: 12px; color: var(--text-soft); flex: none; }
    .vnr-cp__tg .t { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); }
    .vnr-cp__tg .c { font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); font-variant-numeric: tabular-nums; }
    .vnr-cp[data-top='error'] .vnr-cp__tg .c { color: var(--error-base); }
    .vnr-cp[data-top='warn']  .vnr-cp__tg .c { color: var(--warning-base); }
    .vnr-cp[data-top='info']  .vnr-cp__tg .c { color: var(--info-base); }
    .vnr-cp__tg .c.is-ok { color: var(--success-base); }
    .vnr-cp__tg .sp { margin-inline-start: auto; }
    .vnr-cp__tg .ac { font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500); color: var(--text-soft); flex: none; }

    .vnr-cp__bd { display: flex; flex-direction: column; gap: var(--space-3, 12px);
      padding: var(--space-3, 12px); }
    .vnr-cp__gr { display: flex; flex-direction: column; gap: var(--space-2, 8px); }
    .vnr-cp__gh { display: flex; align-items: baseline; gap: var(--space-2, 8px); }
    .vnr-cp__gh .lv { font-size: var(--fs-11, 11px); font-weight: var(--font-bold, 700); text-transform: uppercase;
      letter-spacing: .3px; color: var(--text-soft); }
    .vnr-cp__gr[data-lv='error'] .vnr-cp__gh .lv { color: var(--error-base); }
    .vnr-cp__gr[data-lv='warn']  .vnr-cp__gh .lv { color: var(--warning-base); }
    .vnr-cp__gh .n { font-size: var(--fs-11, 11px); color: var(--text-soft);
      font-variant-numeric: tabular-nums; }

    /* Mức error nổi bật nhất: viền trái dày + nền lỗi + tiêu đề đậm hơn.
       (Lưu ý: KHÔNG đặt dấu backtick trong comment CSS — nó đóng template literal sớm,
        biến styles thành mảng nhiều phần tử ⇒ lỗi "Failed to resolve styles at position 1".) */
    .vnr-cp__it { border: 1px solid var(--border-soft);
      border-inline-start: 3px solid var(--border-sub); border-radius: var(--radius-xs, 4px);
      background: var(--bg-surface); padding: var(--space-2, 8px) var(--space-2-5, 10px); }
    .vnr-cp__it[data-lv='error'] { border-color: var(--error-base); border-inline-start-color: var(--error-base);
      background: var(--error-bg); }
    .vnr-cp__it[data-lv='warn'] { border-color: var(--warning-border);
      border-inline-start-color: var(--warning-base); background: var(--warning-bg); }
    .vnr-cp__it[data-lv='info'] { border-inline-start-color: var(--info-base);
      background: var(--info-bg); }

    .vnr-cp__it .hd { display: flex; align-items: baseline; gap: var(--space-2, 8px); flex-wrap: wrap; }
    .vnr-cp__it .tag { flex: none; font-size: var(--fs-11, 11px); font-weight: var(--font-bold, 700); text-transform: uppercase;
      letter-spacing: .3px; border-radius: var(--radius-full); padding: 1px 8px; background: var(--bg-surface);
      border: 1px solid var(--border-sub); color: var(--text-sub); }
    .vnr-cp__it[data-lv='error'] .tag { color: var(--error-base); border-color: var(--error-base); }
    .vnr-cp__it[data-lv='warn']  .tag { color: var(--warning-base); border-color: var(--warning-border); }
    .vnr-cp__it[data-lv='info']  .tag { color: var(--info-base);
      border-color: var(--info-base); }
    .vnr-cp__it .ti { font-size: var(--fs-13, 13px); font-weight: var(--font-medium, 500); color: var(--text-strong);
      word-break: break-word; }
    .vnr-cp__it[data-lv='error'] .ti { font-weight: var(--font-semibold, 600); }
    .vnr-cp__it .de { margin: var(--space-1, 4px) 0 0; font-size: var(--fs-12, 12px);
      color: var(--text-body); line-height: 1.5; }
    .vnr-cp__it .ft { display: flex; align-items: center; gap: var(--space-2, 8px);
      margin-block-start: var(--space-2, 8px); flex-wrap: wrap; }
    .vnr-cp__it .sr { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-cp__it .sp { margin-inline-start: auto; }

    .vnr-cp__b { border: 1px solid var(--border-sub); background: var(--bg-surface); color: var(--text-body);
      font: inherit; font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500); cursor: pointer;
      border-radius: var(--radius-xs, 4px); padding: 3px 9px; }
    .vnr-cp__b:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .vnr-cp__b:focus-visible { outline: 2px solid var(--primary-base); outline-offset: 1px; }
    .vnr-cp__b.is-primary { border-color: var(--primary-base); color: var(--primary-base);
      background: var(--primary-bg-subtle); font-weight: var(--font-semibold, 600); }
    .vnr-cp__b.is-primary:hover { background: var(--bg-surface); }

    /* Container hẹp: nút xuống dòng thay vì ép chữ ⇒ không cuộn ngang.
       Biến số cột KHÔNG khai ở đây — phần tử mang container-type không tự query được chính nó. */
    @container vnrform (max-width: 559px) {
      .vnr-cp__it .ft { align-items: stretch; flex-direction: column; }
      .vnr-cp__it .sp { margin-inline-start: 0; }
      .vnr-cp__b { inline-size: 100%; padding-block: 6px; }
      .vnr-cp__tg .ac { display: none; }
    }
  `],
})
export class VnrConflictPanel {
  /** Danh sách xung đột ĐÃ ĐƯỢC PHÁT HIỆN bởi tầng nghiệp vụ. */
  readonly conflicts = input<readonly VnrConflictItem[]>([]);
  readonly title = input('Xung đột & cảnh báo');
  /** Trạng thái ban đầu; sau đó người dùng tự thu gọn/mở rộng. */
  readonly collapsedByDefault = input(false);

  /** Người dùng bấm nút xử lý của một mục — caller quyết định làm gì. */
  readonly resolve = output<string>();
  /** Người dùng muốn xem chi tiết nguồn gốc xung đột. */
  readonly inspect = output<string>();

  /** `null` = chưa can thiệp ⇒ bám theo `collapsedByDefault`. */
  private readonly userCollapsed = signal<boolean | null>(null);

  protected readonly collapsed = computed(
    () => this.userCollapsed() ?? this.collapsedByDefault(),
  );

  /** Đếm theo mức — dùng cho nhãn tiêu đề và mức nổi bật nhất. */
  private readonly counts = computed(() => {
    const c: Record<VnrConflictLevel, number> = { error: 0, warn: 0, info: 0 };
    for (const item of this.conflicts()) c[item.level] += 1;
    return c;
  });

  /** Vd "2 lỗi · 1 cảnh báo"; rỗng khi không có xung đột nào. */
  protected readonly countLabel = computed(() => {
    const c = this.counts();
    return VNR_CONFLICT_ORDER
      .filter((lv) => c[lv] > 0)
      .map((lv) => c[lv] + ' ' + VNR_CONFLICT_NOUN[lv])
      .join(' · ');
  });

  /** Mức nặng nhất đang có — quyết định tông của cả panel. */
  protected readonly topLevel = computed(() => {
    const c = this.counts();
    return VNR_CONFLICT_ORDER.find((lv) => c[lv] > 0) ?? 'none';
  });

  /** Gom nhóm theo mức, giữ nguyên thứ tự caller truyền trong từng nhóm. */
  protected readonly groups = computed<readonly VnrConflictGroup[]>(() => {
    const all = this.conflicts();
    return VNR_CONFLICT_ORDER
      .map((level) => ({
        level,
        label: VNR_CONFLICT_LABEL[level],
        items: all.filter((item) => item.level === level),
      }))
      .filter((g) => g.items.length > 0);
  });

  protected toggle(): void {
    this.userCollapsed.set(!this.collapsed());
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · unsaved-guard — chặn rời form khi còn thay đổi chưa lưu
// ══════════════════════════════════════════════════════════════════════════════

/** Đếm instance để sinh id duy nhất cho `aria-labelledby` (encapsulation None ⇒ id là toàn cục). */
let vnrUnsavedGuardSeq = 0;

/**
 * Chặn rời form khi còn thay đổi chưa lưu — gồm 3 lớp bảo vệ:
 *   1. Dải nhắc thường trực "Có N thay đổi chưa lưu" khi `dirty`.
 *   2. Hộp thoại xác nhận (overlay tự dựng, KHÔNG phụ thuộc modal ngoài) khi `open` = true.
 *   3. Sự kiện `beforeunload` của trình duyệt để chặn đóng/tải lại tab khi `dirty`.
 *
 * RANH GIỚI: component KHÔNG tự tính form có dirty hay không, KHÔNG tự điều hướng.
 * Caller (route guard / form state) truyền `dirty`, bật `open`, rồi nghe `confirmLeave`
 * hoặc `cancelLeave` để tự quyết định đi tiếp hay ở lại.
 *
 * AN TOÀN SSR-LESS: mọi truy cập `window` đều nằm sau kiểm tra `typeof window !== 'undefined'`;
 * listener được gỡ bằng cleanup của `effect()` và một lần nữa qua `DestroyRef` khi huỷ.
 */
@Component({
  selector: 'vnr-unsaved-guard',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    @if (dirty()) {
      <div class="vnr-ug__bar" role="status">
        <span class="dot" aria-hidden="true"></span>
        <span class="tx">{{ barLabel() }}</span>
        <span class="sp"></span>
        <!-- Slot cho nút Lưu / Huỷ do caller cắm vào -->
        <ng-content select="[guardActions]" />
      </div>
    }

    @if (open()) {
      <div class="vnr-ug__ov">
        <div class="vnr-ug__bd" (click)="cancel()"></div>
        <div #dlg class="vnr-ug__dlg" role="dialog" aria-modal="true" [attr.aria-labelledby]="titleId"
          [attr.aria-describedby]="msgId"
          tabindex="-1" (keydown.escape)="cancel()" (keydown)="trap($event)">
          <h2 class="vnr-ug__t" [id]="titleId">Còn thay đổi chưa lưu</h2>
          <p class="vnr-ug__m" [id]="msgId">{{ message() }}</p>
          @if (changeCount(); as n) {
            <p class="vnr-ug__n">Số thay đổi sẽ mất: <b>{{ n }}</b></p>
          }
          <div class="vnr-ug__ft">
            <button #stayBtn type="button" class="vnr-ug__b is-primary" (click)="cancel()">{{ stayLabel() }}</button>
            <button type="button" class="vnr-ug__b is-danger" (click)="confirm()">{{ leaveLabel() }}</button>
          </div>
        </div>
      </div>
    }
  `,
  styles: [`
    /* Guard chiếm trọn hàng khi đặt trong .vnr-fg ⇒ nhắm PHẦN TỬ HOST (grid item thật),
       không phải div con bên trong. */
    vnr-unsaved-guard { display: block; min-inline-size: 0; }
    .vnr-fg > vnr-unsaved-guard { grid-column: 1 / -1; }

    .vnr-ug__bar { display: flex; align-items: center; gap: var(--space-2, 8px);
      padding: var(--space-2, 8px) var(--space-3, 12px); border: 1px solid var(--warning-border);
      border-radius: var(--radius-sm, 6px); background: var(--warning-bg); }
    .vnr-ug__bar .dot { inline-size: 8px; block-size: 8px; border-radius: var(--radius-full);
      background: var(--warning-base); flex: none; }
    .vnr-ug__bar .tx { font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); color: var(--warning-base); }
    .vnr-ug__bar .sp { margin-inline-start: auto; }

    .vnr-ug__ov { position: fixed; inset: 0; z-index: 1000;
      display: flex; align-items: center; justify-content: center; padding: var(--space-4, 16px); }
    .vnr-ug__bd { position: absolute; inset: 0; background: var(--overlay); }
    .vnr-ug__dlg { position: relative; inline-size: min(420px, 100%);
      background: var(--bg-surface); border: 1px solid var(--border-strong);
      border-radius: var(--radius-sm, 6px); padding: var(--space-4, 16px); }
    .vnr-ug__dlg:focus { outline: none; }
    .vnr-ug__t { margin: 0; font-size: var(--fs-14, 14px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-ug__m { margin: var(--space-2, 8px) 0 0; font-size: var(--fs-13, 13px);
      color: var(--text-body); line-height: 1.55; }
    .vnr-ug__n { margin: var(--space-1, 4px) 0 0; font-size: var(--fs-12, 12px); color: var(--text-sub); }
    .vnr-ug__n b { color: var(--warning-base); font-variant-numeric: tabular-nums; }
    .vnr-ug__ft { display: flex; justify-content: flex-end; gap: var(--space-2, 8px);
      margin-block-start: var(--space-4, 16px); }
    .vnr-ug__b { border: 1px solid var(--border-sub); background: var(--bg-surface); color: var(--text-body);
      font: inherit; font-size: var(--fs-12, 12px); font-weight: var(--font-medium, 500); cursor: pointer;
      border-radius: var(--radius-xs, 4px); padding: 6px 14px; }
    .vnr-ug__b:focus-visible { outline: 2px solid var(--primary-base); outline-offset: 1px; }
    /* Ở lại = lựa chọn AN TOÀN ⇒ nhấn mạnh; Thoát = phá huỷ ⇒ tông lỗi, không mặc định */
    .vnr-ug__b.is-primary { border-color: var(--primary-base); background: var(--primary-base);
      color: var(--text-on-primary); font-weight: var(--font-semibold, 600); }
    .vnr-ug__b.is-danger { color: var(--error-base); border-color: var(--error-base); }
    .vnr-ug__b.is-danger:hover { background: var(--error-bg); }

    /* Container hẹp: dải nhắc và nút xếp dọc cho dễ bấm */
    @container vnrform (max-width: 559px) {
      .vnr-ug__bar { align-items: flex-start; flex-wrap: wrap; }
      .vnr-ug__bar .sp { margin-inline-start: 0; }
      .vnr-ug__ft { flex-direction: column-reverse; }
      .vnr-ug__b { inline-size: 100%; }
    }
  `],
})
export class VnrUnsavedGuard {
  /** Form còn thay đổi chưa lưu hay không — do caller tính, KHÔNG suy diễn trong UI. */
  readonly dirty = input.required<boolean>();
  /** Số thay đổi đang chờ lưu; `null` ⇒ chỉ báo chung, không hiện con số. */
  readonly changeCount = input<number | null>(null);
  readonly message = input('Dữ liệu chưa lưu sẽ mất. Bạn có chắc muốn thoát?');
  readonly stayLabel = input('Ở lại');
  readonly leaveLabel = input('Thoát');
  /** Hai chiều: caller bật để hỏi, component tự tắt sau khi người dùng chọn. */
  readonly open = model(false);

  /** Người dùng chấp nhận mất thay đổi — caller tự điều hướng. */
  readonly confirmLeave = output<void>();
  /** Người dùng chọn ở lại. */
  readonly cancelLeave = output<void>();

  protected readonly titleId = 'vnr-ug-t-' + (++vnrUnsavedGuardSeq);
  protected readonly msgId = 'vnr-ug-m-' + vnrUnsavedGuardSeq;

  /** Phần tử đang giữ tiêu điểm TRƯỚC khi hộp thoại mở — để trả tiêu điểm về đúng chỗ khi đóng. */
  private returnFocusTo: HTMLElement | null = null;

  private readonly dialogEl = viewChild<ElementRef<HTMLElement>>('dlg');
  private readonly stayEl = viewChild<ElementRef<HTMLButtonElement>>('stayBtn');
  private readonly destroyRef = inject(DestroyRef);

  /** Hàm gỡ listener `beforeunload` đang gắn (null = chưa gắn). */
  private detachUnload: (() => void) | null = null;

  protected readonly barLabel = computed(() => {
    const n = this.changeCount();
    return n != null && n > 0 ? 'Có ' + n + ' thay đổi chưa lưu' : 'Có thay đổi chưa lưu';
  });

  constructor() {
    // Chặn đóng/tải lại tab khi còn thay đổi. Listener gắn/gỡ THEO signal `dirty`
    // ⇒ không cần zone.js (app chạy zoneless), và cleanup của effect gỡ đúng handler cũ.
    effect((onCleanup) => {
      if (!this.dirty()) return;
      if (typeof window === 'undefined') return; // an toàn khi không có DOM

      const handler = (e: BeforeUnloadEvent): void => {
        // Trình duyệt hiện đại bỏ qua message tuỳ biến — chỉ cần chặn là đủ.
        e.preventDefault();
        e.returnValue = '';
      };
      window.addEventListener('beforeunload', handler);
      this.detachUnload = () => window.removeEventListener('beforeunload', handler);
      onCleanup(() => this.releaseUnload());
    });

    // Đưa tiêu điểm vào nút an toàn ("Ở lại") khi mở, và TRẢ VỀ chỗ cũ khi đóng.
    // Thiếu vế trả về thì người dùng bàn phím / trình đọc màn hình bị văng lên đầu trang
    // sau khi đóng hộp thoại, mất hoàn toàn vị trí đang thao tác.
    effect(() => {
      if (typeof document === 'undefined') return;
      if (this.open()) {
        const active = document.activeElement;
        this.returnFocusTo = active instanceof HTMLElement ? active : null;
        this.stayEl()?.nativeElement.focus();
        return;
      }
      const back = this.returnFocusTo;
      this.returnFocusTo = null;
      // Chỉ trả tiêu điểm nếu phần tử cũ còn nằm trong tài liệu (form có thể đã bị gỡ khi rời trang).
      if (back?.isConnected) back.focus();
    });

    // Lưới an toàn cuối: dù effect đã cleanup, vẫn bảo đảm không rò listener.
    this.destroyRef.onDestroy(() => this.releaseUnload());
  }

  protected confirm(): void {
    this.open.set(false);
    this.confirmLeave.emit();
  }

  protected cancel(): void {
    this.open.set(false);
    this.cancelLeave.emit();
  }

  /** Giữ tiêu điểm quẩn trong hộp thoại — modal thật thì Tab không được thoát ra ngoài. */
  protected trap(e: KeyboardEvent): void {
    if (e.key !== 'Tab') return;
    const host = this.dialogEl()?.nativeElement;
    if (!host) return;
    const focusable = Array.from(host.querySelectorAll<HTMLElement>('button:not([disabled])'));
    if (!focusable.length) return;

    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const active = host.ownerDocument.activeElement;

    if (e.shiftKey && active === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && active === last) {
      e.preventDefault();
      first.focus();
    }
  }

  private releaseUnload(): void {
    this.detachUnload?.();
    this.detachUnload = null;
  }
}
