import {
  ChangeDetectionStrategy, Component, ViewEncapsulation, computed, input, model, output, signal,
} from '@angular/core';
import { HrmAlert } from 'hrm-ui';

/**
 * @file Form Design System — bộ 3 khối cho trait `effective-dated` · `scheduled` · `audit`.
 *
 * BỔ TRỢ cho `_form-ds.ts`: ở đó `VnrChangeComparison` mới xử lý ngày hiệu lực + lịch thay đổi ở
 * mức TÓM TẮT (chỉ để đọc, gắn liền với bảng so sánh). Ba component dưới đây là bản ĐẦY ĐỦ,
 * dùng ĐỘC LẬP được:
 *   1. `vnr-effective-date-bar`  — KHAI ngày hiệu lực (có nhập liệu, có 2 chế độ áp dụng)
 *   2. `vnr-scheduled-changes`   — DANH SÁCH thay đổi đã lên lịch (sửa / huỷ lịch, cảnh báo trùng)
 *   3. `vnr-audit-timeline`      — LỊCH SỬ thay đổi dạng timeline dọc (vết audit)
 *
 * Dùng chung cho mọi nghiệp vụ "thay đổi có ngày hiệu lực": điều chuyển · thăng chức ·
 * đổi lương · đổi ca · đổi hợp đồng · đổi phòng ban…
 *
 * RANH GIỚI CHUNG (rất quan trọng): các component này KHÔNG chứa nghiệp vụ thời gian.
 * Không tự so ngày để kết luận "tương lai / quá khứ", không tự phát hiện trùng lịch,
 * không tự sắp xếp theo thời gian. Chuỗi ngày ở đây là dd/MM/yyyy — so sánh chuỗi sẽ SAI.
 * Mọi kết luận (`warning`, `conflict`, thứ tự hiển thị) do tầng nghiệp vụ tính sẵn rồi truyền vào.
 */

/** Bộ đếm sinh id duy nhất cho cặp label/input — tránh trùng khi đặt nhiều bar trên một trang. */
let vnrTimelineUid = 0;

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · effective-dated — thanh khai NGÀY HIỆU LỰC
// ══════════════════════════════════════════════════════════════════════════════

/** Chế độ áp dụng thay đổi: có hiệu lực ngay, hay hẹn trước tới một ngày cụ thể. */
export type VnrEffectiveMode = 'immediate' | 'scheduled';

/** Một lựa chọn trên thanh chọn chế độ — nhãn + câu giải thích ngắn. */
export interface VnrEffectiveModeOption {
  readonly value: VnrEffectiveMode;
  readonly label: string;
  readonly hint: string;
}

/**
 * Thanh khai NGÀY HIỆU LỰC cho thay đổi nhân sự.
 *
 * Vì sao tách riêng: mọi thay đổi nhân sự đều phải trả lời câu hỏi "áp dụng từ khi nào" TRƯỚC khi
 * điền nội dung thay đổi — đặt câu hỏi đó lên đầu form giúp người dùng không nhập xong mới phát
 * hiện chọn sai mốc thời gian.
 *
 * RANH GIỚI: component KHÔNG so ngày, KHÔNG tự kết luận "ngày này trong quá khứ / trùng kỳ lương /
 * đã chốt công". Caller tính rồi truyền `warning` — nhờ vậy cùng một thanh dùng được cho điều chuyển,
 * thăng chức, đổi lương, đổi ca mà mỗi nghiệp vụ có luật cảnh báo riêng.
 *
 * `minDate` / `maxDate` chỉ để HIỂN THỊ khoảng cho phép, không dùng để chặn nhập (chặn là việc của
 * validator ở tầng form).
 */
@Component({
  selector: 'vnr-effective-date-bar',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [HrmAlert],
  template: `
    <div class="vnr-eb">
      <div class="vnr-eb__row">
        <span class="vnr-eb__lb">Ngày hiệu lực</span>

        @if (readonly()) {
          <span class="vnr-eb__ro">{{ readonlyText() }}</span>
        } @else {
          <div class="vnr-eb__seg" role="radiogroup" aria-label="Thời điểm áp dụng thay đổi">
            @for (o of options; track o.value) {
              <button type="button" class="vnr-eb__opt" role="radio"
                [class.is-on]="mode() === o.value"
                [attr.aria-checked]="mode() === o.value"
                (click)="pickMode(o.value)">{{ o.label }}</button>
            }
          </div>
          <span class="vnr-eb__note">{{ activeHint() }}</span>
        }
      </div>

      <!-- Ô nhập ngày CHỈ xuất hiện ở chế độ hẹn trước — chế độ áp dụng ngay không cần khai ngày -->
      @if (mode() === 'scheduled') {
        <div class="vnr-eb__bd">
          <label class="vnr-eb__dl" [attr.for]="inputId">Áp dụng từ ngày</label>
          @if (readonly()) {
            <span class="vnr-eb__dv">{{ effectiveDate() || '—' }}</span>
          } @else {
            <input class="vnr-eb__in" type="text" inputmode="numeric" autocomplete="off"
              placeholder="dd/MM/yyyy" [id]="inputId" [value]="effectiveDate()"
              (change)="setDate($event)" />
          }
          @if (rangeHint()) { <span class="vnr-eb__hint">{{ rangeHint() }}</span> }
        </div>
      }

      <!-- Cảnh báo do caller truyền vào — dùng hrm-alert của design system: nền + icon + nhãn CHỮ
           "Lưu ý" nên không phụ thuộc màu. Dạng banner để nằm gọn thành dải cuối thẻ, không lồng hộp.
           Bọc role="status" aria-live="polite" vì cảnh báo xuất hiện/biến mất theo ngày người dùng
           chọn — trình đọc màn hình phải đọc lên ngay lúc nó hiện ra. -->
      @if (warning(); as w) {
        <div role="status" aria-live="polite">
          <hrm-alert type="warning" [banner]="true" message="Lưu ý" [description]="w" />
        </div>
      }
    </div>
  `,
  styles: [`
    /* Grid item THẬT là phần tử host, không phải div bên trong — nên span cột khai ở đây.
       (Nhắc lại lỗi đã gặp: đặt grid-column lên div con thì hoàn toàn vô tác dụng.) */
    vnr-effective-date-bar { display: block; min-inline-size: 0; }
    .vnr-fg > vnr-effective-date-bar { grid-column: 1 / -1; }

    .vnr-eb { border: 1px solid var(--border-sub); border-radius: var(--radius-sm, 6px);
      background: var(--bg-surface); overflow: hidden; }
    .vnr-eb__row { display: flex; align-items: center; flex-wrap: wrap; gap: var(--space-3, 12px);
      padding: var(--space-2-5, 10px) var(--space-3, 12px); background: var(--bg-surface-subtle);
      border-block-end: 1px solid var(--border-soft); }
    .vnr-eb__lb { font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-eb__ro { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong);
      font-variant-numeric: tabular-nums; }

    /* Segmented tự dựng bằng button — không kéo thêm component ngoài vào shell của form */
    .vnr-eb__seg { display: inline-flex; gap: 2px; padding: 2px; border: 1px solid var(--border-sub);
      border-radius: var(--radius-sm, 6px); background: var(--faded-bg); }
    .vnr-eb__opt { border: 1px solid transparent; background: none; color: var(--text-sub); font: inherit;
      font-size: var(--fs-12, 12px); padding: 4px 12px; border-radius: var(--radius-xs, 4px);
      cursor: pointer; white-space: nowrap; }
    .vnr-eb__opt:hover { color: var(--text-strong); }
    /* Trạng thái chọn không chỉ dựa vào màu: có nền nổi, viền và chữ đậm hơn */
    .vnr-eb__opt.is-on { background: var(--bg-surface); border-color: var(--primary-base);
      color: var(--primary-base); font-weight: var(--font-semibold, 600); }
    .vnr-eb__opt:focus-visible { outline: 2px solid var(--primary-base); outline-offset: 1px; }
    .vnr-eb__note { font-size: var(--fs-11, 11px); color: var(--text-soft); }

    .vnr-eb__bd { display: flex; align-items: center; flex-wrap: wrap;
      gap: var(--space-2, 8px) var(--space-3, 12px); padding: var(--space-2-5, 10px) var(--space-3, 12px); }
    .vnr-eb__dl { font-size: var(--fs-12, 12px); color: var(--text-sub); }
    .vnr-eb__in { inline-size: 136px; block-size: 30px; box-sizing: border-box;
      border: 1px solid var(--border-sub); border-radius: var(--radius-xs, 4px); background: var(--bg-surface);
      padding: 0 var(--space-2, 8px); font: inherit; font-size: var(--fs-13, 13px);
      color: var(--text-strong); font-variant-numeric: tabular-nums; }
    .vnr-eb__in:focus-visible { outline: 2px solid var(--primary-base); outline-offset: 1px; }
    .vnr-eb__in:focus { outline: none; border-color: var(--primary-base); }
    .vnr-eb__dv { font-size: var(--fs-13, 13px); font-weight: var(--font-semibold, 600); color: var(--text-strong);
      font-variant-numeric: tabular-nums; }
    .vnr-eb__hint { font-size: var(--fs-11, 11px); color: var(--text-soft); }

    /* Vùng chứa hẹp: xếp dọc, segmented và ô ngày trải hết bề ngang cho dễ bấm */
    @container vnrform (max-width: 559px) {
      .vnr-eb__row { flex-direction: column; align-items: stretch; gap: var(--space-2, 8px); }
      .vnr-eb__seg { display: flex; }
      .vnr-eb__opt { flex: 1; text-align: center; }
      .vnr-eb__bd { flex-direction: column; align-items: stretch; }
      .vnr-eb__in { inline-size: 100%; }
    }
  `],
})
export class VnrEffectiveDateBar {
  /** Chuỗi dd/MM/yyyy — hai chiều để form cha giữ nguyên định dạng người dùng nhìn thấy. */
  readonly effectiveDate = model('');
  readonly mode = model<VnrEffectiveMode>('immediate');
  /** Chỉ để hiển thị khoảng cho phép (dd/MM/yyyy) — KHÔNG dùng để chặn nhập. */
  readonly minDate = input<string | null>(null);
  readonly maxDate = input<string | null>(null);
  /** Cảnh báo nghiệp vụ ĐÃ TÍNH bởi caller, vd "Ngày hiệu lực rơi vào kỳ lương đã chốt". */
  readonly warning = input<string | null>(null);
  readonly readonly = input(false);

  readonly dateChange = output<string>();

  protected readonly inputId = 'vnr-eb-date-' + ++vnrTimelineUid;

  protected readonly options: readonly VnrEffectiveModeOption[] = [
    { value: 'immediate', label: 'Áp dụng ngay', hint: 'Thay đổi có hiệu lực ngay khi hồ sơ được duyệt.' },
    { value: 'scheduled', label: 'Lên lịch trước', hint: 'Thay đổi chỉ có hiệu lực kể từ ngày đã chọn.' },
  ];

  protected readonly activeHint = computed(
    () => this.options.find((o) => o.value === this.mode())?.hint ?? '',
  );

  /** Chỉ ghép chuỗi để hiển thị khoảng hợp lệ — không so sánh, không suy luận. */
  protected readonly rangeHint = computed(() => {
    const min = this.minDate();
    const max = this.maxDate();
    if (min && max) return 'Chỉ nhận ngày trong khoảng ' + min + ' – ' + max + '.';
    if (min) return 'Chỉ nhận ngày từ ' + min + ' trở đi.';
    if (max) return 'Chỉ nhận ngày đến ' + max + '.';
    return null;
  });

  protected readonly readonlyText = computed(() => {
    if (this.mode() === 'immediate') return 'Áp dụng ngay';
    return this.effectiveDate() || 'Chưa chọn ngày hiệu lực';
  });

  protected pickMode(m: VnrEffectiveMode): void {
    if (this.readonly() || this.mode() === m) return;
    // Giữ nguyên giá trị ngày đã nhập khi chuyển về "áp dụng ngay": người dùng đổi ý quay lại
    // vẫn còn ngày cũ, đỡ phải gõ lại. Việc bỏ qua ngày này là quyết định của tầng nghiệp vụ.
    this.mode.set(m);
  }

  protected setDate(e: Event): void {
    const v = (e.target as HTMLInputElement).value.trim();
    this.effectiveDate.set(v);
    this.dateChange.emit(v);
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · scheduled — thay đổi ĐÃ LÊN LỊCH trong tương lai
// ══════════════════════════════════════════════════════════════════════════════

/** Vòng đời của một thay đổi đã lên lịch. */
export type VnrScheduledStatus = 'scheduled' | 'applied' | 'cancelled';

/**
 * Một thay đổi đã lên lịch.
 * Đặt tên `...Item` để không đụng `VnrScheduledChange` (bản rút gọn) trong `_form-ds.ts` —
 * hai kiểu có thể cùng được import vào một trang.
 */
export interface VnrScheduledChangeItem {
  readonly id: string;
  /** dd/MM/yyyy — chỉ để hiển thị, component không parse. */
  readonly effectiveDate: string;
  readonly title: string;
  readonly summary?: string | null;
  readonly status: VnrScheduledStatus;
  /** Xung đột do domain service phát hiện (trùng ngày, chồng lấn quyết định…). */
  readonly conflict?: boolean;
  /** Câu giải thích xung đột — BẮT BUỘC có nội dung khi conflict = true, để không chỉ dựa vào màu. */
  readonly conflictNote?: string | null;
}

/**
 * Danh sách thay đổi ĐÃ LÊN LỊCH — tấm chắn chống ghi đè lịch sử.
 *
 * Bài toán thật: một nhân viên có thể đã có quyết định điều chuyển hiệu lực 01/09 nằm chờ; nếu người
 * dùng tạo tiếp quyết định đổi lương hiệu lực 01/09 mà không thấy cái đang chờ, dữ liệu lịch sử sẽ bị
 * đè. Khối này hiển thị toàn bộ hàng chờ ngay trong form để người dùng nhìn thấy TRƯỚC khi lưu.
 *
 * RANH GIỚI:
 * - KHÔNG tự sắp xếp. Chuỗi dd/MM/yyyy sắp theo thứ tự chuỗi sẽ sai (02/01 đứng trước 15/12 nhưng
 *   "15/12/2025" < "02/01/2026" là sai). Caller sắp sẵn, component render đúng thứ tự nhận được.
 * - KHÔNG tự phát hiện xung đột — nhận `conflict` + `conflictNote` đã tính.
 * - KHÔNG tự quyết quyền: `readonly` do caller cấp.
 */
@Component({
  selector: 'vnr-scheduled-changes',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <ul class="vnr-sl">
      @for (c of changes(); track c.id) {
        <li class="vnr-sl__it" [attr.data-status]="c.status" [class.has-cf]="!!c.conflict">
          <div class="vnr-sl__bd">
            <div class="vnr-sl__hd">
              <span class="dt">{{ c.effectiveDate }}</span>
              <span class="ti">{{ c.title }}</span>
              <span class="st" [attr.data-status]="c.status">{{ statusLabel(c.status) }}</span>
            </div>
            @if (c.summary) { <p class="vnr-sl__sum">{{ c.summary }}</p> }
            <!-- Xung đột: tô nền KÈM CHỮ giải thích — người mù màu vẫn đọc được lý do -->
            @if (c.conflict) {
              <p class="vnr-sl__cf">{{ c.conflictNote || 'Trùng ngày hiệu lực với một thay đổi khác.' }}</p>
            }
          </div>

          @if (!readonly() && c.status !== 'cancelled') {
            <div class="vnr-sl__act">
              <button type="button" class="vnr-sl__b" (click)="edit.emit(c.id)">Sửa</button>
              <!-- Đã áp dụng thì không còn gì để huỷ: phải làm quyết định điều chỉnh, không xoá lịch -->
              @if (c.status === 'scheduled') {
                <button type="button" class="vnr-sl__b is-danger" (click)="cancel.emit(c.id)">Huỷ lịch</button>
              }
            </div>
          }
        </li>
      } @empty {
        <li class="vnr-sl__empty">Chưa có thay đổi nào được lên lịch.</li>
      }
    </ul>
  `,
  styles: [`
    vnr-scheduled-changes { display: block; min-inline-size: 0; }
    .vnr-fg > vnr-scheduled-changes { grid-column: 1 / -1; }

    .vnr-sl { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column;
      gap: var(--space-2, 8px); }
    .vnr-sl__it { display: flex; align-items: flex-start; gap: var(--space-3, 12px);
      border: 1px solid var(--border-sub); border-inline-start: 3px solid var(--border-strong);
      border-radius: var(--radius-sm, 6px); background: var(--bg-surface);
      padding: var(--space-2, 8px) var(--space-3, 12px); }
    .vnr-sl__bd { flex: 1; min-inline-size: 0; }
    .vnr-sl__hd { display: flex; align-items: baseline; flex-wrap: wrap; gap: var(--space-2, 8px); }
    .vnr-sl__hd .dt { flex: none; font-size: var(--fs-13, 13px); font-weight: var(--font-bold, 700); color: var(--text-strong);
      font-variant-numeric: tabular-nums; }
    .vnr-sl__hd .ti { font-size: var(--fs-13, 13px); color: var(--text-body); word-break: break-word; }
    .vnr-sl__hd .st { margin-inline-start: auto; flex: none; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600);
      border-radius: var(--radius-full); padding: 1px 9px; }
    .vnr-sl__sum { margin: var(--space-1, 4px) 0 0; font-size: var(--fs-12, 12px); color: var(--text-sub); }

    /* Trạng thái: mỗi trạng thái có VIỀN TRÁI + NHÃN CHỮ riêng, màu chỉ là lớp bổ trợ */
    .vnr-sl__it[data-status='scheduled'] { border-inline-start-color: var(--primary-base); }
    .vnr-sl__it[data-status='applied']   { border-inline-start-color: var(--success-base); }
    .vnr-sl__it[data-status='cancelled'] { border-inline-start-color: var(--faded-base); }
    .vnr-sl__hd .st[data-status='scheduled'] { color: var(--primary-base); background: var(--primary-bg-subtle); }
    .vnr-sl__hd .st[data-status='applied']   { color: var(--success-base); background: var(--success-bg); }
    .vnr-sl__hd .st[data-status='cancelled'] { color: var(--faded-base); background: var(--faded-bg); }

    /* Đã huỷ: gạch ngang + mờ, mắt lướt qua ngay nhưng vẫn tra cứu được */
    .vnr-sl__it[data-status='cancelled'] { opacity: .6; background: var(--bg-surface-subtle); }
    .vnr-sl__it[data-status='cancelled'] .dt,
    .vnr-sl__it[data-status='cancelled'] .ti,
    .vnr-sl__it[data-status='cancelled'] .vnr-sl__sum { text-decoration: line-through; }

    /* Xung đột thắng thế về mặt thị giác so với màu trạng thái */
    .vnr-sl__it.has-cf { background: var(--warning-bg);
      border-color: var(--warning-border); border-inline-start-color: var(--warning-base); }
    .vnr-sl__cf { margin: var(--space-1, 4px) 0 0; font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600);
      color: var(--warning-base); }

    .vnr-sl__act { flex: none; display: flex; align-items: center; gap: var(--space-1, 4px); }
    .vnr-sl__b { border: none; background: none; color: var(--primary-base); font: inherit;
      font-size: var(--fs-11, 11px); font-weight: var(--font-medium, 500); cursor: pointer;
      border-radius: var(--radius-xs, 4px); padding: 3px 8px; }
    .vnr-sl__b:hover { background: var(--primary-bg-subtle); }
    .vnr-sl__b.is-danger { color: var(--text-sub); }
    .vnr-sl__b.is-danger:hover { background: var(--error-bg); color: var(--error-base); }

    .vnr-sl__empty { text-align: center; color: var(--text-soft); font-size: var(--fs-12, 12px);
      padding: var(--space-4, 16px); border: 1px dashed var(--border-strong);
      border-radius: var(--radius-sm, 6px); }

    /* Vùng chứa hẹp: nút hành động xuống dòng riêng, tránh bóp nát tiêu đề */
    @container vnrform (max-width: 559px) {
      .vnr-sl__it { flex-direction: column; gap: var(--space-2, 8px); }
      .vnr-sl__hd .st { margin-inline-start: 0; }
      .vnr-sl__act { align-self: flex-end; }
    }
  `],
})
export class VnrScheduledChanges {
  /** ĐÃ ĐƯỢC SẮP XẾP bởi caller — component render nguyên thứ tự nhận vào. */
  readonly changes = input.required<readonly VnrScheduledChangeItem[]>();
  readonly readonly = input(false);

  readonly cancel = output<string>();
  readonly edit = output<string>();

  protected statusLabel(s: VnrScheduledStatus): string {
    return s === 'applied' ? 'Đã áp dụng' : s === 'cancelled' ? 'Đã huỷ' : 'Đã lên lịch';
  }
}

// ══════════════════════════════════════════════════════════════════════════════
// TRAIT · audit — lịch sử thay đổi / vết audit
// ══════════════════════════════════════════════════════════════════════════════

/** Một mốc trong vết audit. Mọi trường đã được tầng nghiệp vụ định dạng sẵn thành chuỗi hiển thị. */
export interface VnrAuditEntry {
  readonly id: string;
  /** Mốc thời gian ĐÃ ĐỊNH DẠNG để hiển thị, vd "04/08/2026 09:12". */
  readonly at: string;
  readonly actor: string;
  readonly actorRole?: string | null;
  /** Hành động, vd "Cập nhật hồ sơ", "Duyệt yêu cầu", "Huỷ lịch điều chuyển". */
  readonly action: string;
  /** Trường bị tác động, vd "Lương cơ bản". */
  readonly field?: string | null;
  readonly from?: string | null;
  readonly to?: string | null;
  readonly note?: string | null;
}

/**
 * Lịch sử thay đổi dạng timeline dọc — trả lời "ai đổi gì, lúc nào, từ giá trị nào sang giá trị nào".
 *
 * Dùng cho: hồ sơ nhân viên · quyết định · yêu cầu phê duyệt · cấu hình hệ thống.
 *
 * RANH GIỚI: KHÔNG sắp xếp lại, KHÔNG tính "cách đây bao lâu", KHÔNG gom nhóm theo ngày.
 * `at` là chuỗi ĐÃ ĐỊNH DẠNG; thứ tự hiển thị đúng bằng thứ tự caller truyền vào.
 *
 * Thu gọn: `collapsedCount` = số mục hiện ban đầu (0 = hiện hết). Bấm "Xem thêm" vừa mở tại chỗ
 * (để dùng được ngay cả khi caller không xử lý gì) vừa bắn `expand` cho caller nạp thêm dữ liệu.
 */
@Component({
  selector: 'vnr-audit-timeline',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  template: `
    <div class="vnr-tl">
      <ol class="vnr-tl__list">
        @for (e of visible(); track e.id) {
          <li class="vnr-tl__it">
            <span class="vnr-tl__mk" aria-hidden="true"><i></i></span>
            <div class="vnr-tl__bd">
              <div class="vnr-tl__hd">
                <span class="at">{{ e.at }}</span>
                <span class="ac">{{ e.actor }}</span>
                @if (e.actorRole) { <span class="rl">{{ e.actorRole }}</span> }
              </div>
              <div class="vnr-tl__ac">
                <span class="act">{{ e.action }}</span>
                @if (e.field) { <span class="fd">{{ e.field }}</span> }
              </div>
              <!-- Cặp giá trị có nhãn CHỮ "Từ … thành …" để đọc được không cần nhìn màu -->
              @if (e.from || e.to) {
                <div class="vnr-tl__df">
                  <span class="k">Từ</span><span class="fr">{{ e.from || '—' }}</span>
                  <span class="ar">→</span>
                  <span class="k">thành</span><span class="to">{{ e.to || '—' }}</span>
                </div>
              }
              @if (e.note) { <p class="vnr-tl__nt">{{ e.note }}</p> }
            </div>
          </li>
        } @empty {
          <li class="vnr-tl__empty">{{ emptyText() }}</li>
        }
      </ol>

      @if (hiddenCount() > 0) {
        <button type="button" class="vnr-tl__more" (click)="showAll()">Xem thêm {{ hiddenCount() }} mục</button>
      }
    </div>
  `,
  styles: [`
    vnr-audit-timeline { display: block; min-inline-size: 0; }
    .vnr-fg > vnr-audit-timeline { grid-column: 1 / -1; }

    .vnr-tl__list { list-style: none; margin: 0; padding: 0; }
    .vnr-tl__it { display: flex; align-items: stretch; gap: var(--space-2-5, 10px);
      padding-block: var(--space-2, 8px); }

    /* Cột mốc: đường nối chạy suốt chiều cao mục nên các mục nối liền mạch,
       chấm mốc vẽ đè lên đường nhờ z-index. */
    .vnr-tl__mk { position: relative; flex: none; inline-size: 12px; align-self: stretch; }
    .vnr-tl__mk i { position: absolute; inset-block-start: 5px; inset-inline-start: 0;
      inline-size: 12px; block-size: 12px; box-sizing: border-box; border-radius: var(--radius-full); z-index: 1;
      background: var(--bg-surface); border: 2px solid var(--border-strong); }
    .vnr-tl__mk::after { content: ''; position: absolute; inset-block: 0; inset-inline-start: 5px;
      inline-size: 2px; background: var(--border-sub); }
    /* Mục đầu: đường bắt đầu từ tâm chấm. Mục cuối: đường dừng tại tâm chấm (11px). */
    .vnr-tl__it:first-child .vnr-tl__mk::after { inset-block-start: 11px; }
    .vnr-tl__it:last-child  .vnr-tl__mk::after { inset-block-end: calc(100% - 11px); }

    .vnr-tl__bd { flex: 1; min-inline-size: 0; }
    .vnr-tl__hd { display: flex; align-items: baseline; flex-wrap: wrap; gap: var(--space-2, 8px); }
    .vnr-tl__hd .at { font-size: var(--fs-11, 11px); color: var(--text-soft);
      font-variant-numeric: tabular-nums; }
    .vnr-tl__hd .ac { font-size: var(--fs-12, 12px); font-weight: var(--font-semibold, 600); color: var(--text-strong); }
    .vnr-tl__hd .rl { font-size: var(--fs-11, 11px); color: var(--info-base);
      background: var(--info-bg); border-radius: var(--radius-full); padding: 1px 8px; }

    .vnr-tl__ac { display: flex; align-items: baseline; flex-wrap: wrap; gap: var(--space-2, 8px);
      margin-block-start: 2px; }
    .vnr-tl__ac .act { font-size: var(--fs-13, 13px); color: var(--text-body); }
    .vnr-tl__ac .fd { font-size: var(--fs-11, 11px); font-weight: var(--font-semibold, 600); color: var(--text-sub);
      background: var(--bg-surface-subtle); border: 1px solid var(--border-soft);
      border-radius: var(--radius-xs, 4px); padding: 1px 7px; }

    .vnr-tl__df { display: flex; align-items: baseline; flex-wrap: wrap; gap: var(--space-1, 4px);
      margin-block-start: var(--space-1, 4px); font-size: var(--fs-12, 12px); }
    .vnr-tl__df .k { font-size: var(--fs-11, 11px); color: var(--text-soft); }
    .vnr-tl__df .fr { color: var(--text-sub); text-decoration: line-through; word-break: break-word; }
    .vnr-tl__df .ar { color: var(--text-soft); }
    /* Giá trị mới đậm hơn hẳn giá trị cũ — mắt bắt ngay cái đang có hiệu lực */
    .vnr-tl__df .to { font-weight: var(--font-semibold, 600); color: var(--text-strong); word-break: break-word; }

    .vnr-tl__nt { margin: var(--space-1, 4px) 0 0; font-size: var(--fs-11, 11px); color: var(--text-sub);
      border-inline-start: 2px solid var(--border-sub); padding-inline-start: var(--space-2, 8px); }

    .vnr-tl__empty { text-align: center; color: var(--text-soft); font-size: var(--fs-12, 12px);
      padding: var(--space-4, 16px); border: 1px dashed var(--border-strong);
      border-radius: var(--radius-sm, 6px); }

    .vnr-tl__more { inline-size: 100%; margin-block-start: var(--space-2, 8px);
      border: 1px dashed var(--border-strong); background: none; color: var(--text-body);
      border-radius: var(--radius-sm, 6px); padding: 6px var(--space-3, 12px); font: inherit;
      font-size: var(--fs-12, 12px); cursor: pointer; }
    .vnr-tl__more:hover { border-color: var(--primary-base); color: var(--primary-base); }

    /* Vùng chứa hẹp: cặp giá trị cũ/mới xếp dọc cho khỏi vỡ dòng giữa chừng */
    @container vnrform (max-width: 559px) {
      .vnr-tl__df { display: grid; grid-template-columns: auto 1fr; gap: 2px var(--space-1, 4px); }
      .vnr-tl__df .ar { display: none; }
    }
  `],
})
export class VnrAuditTimeline {
  /** ĐÃ ĐƯỢC SẮP XẾP bởi caller — component không đụng vào thứ tự. */
  readonly entries = input.required<readonly VnrAuditEntry[]>();
  /** Số mục hiện ban đầu; 0 = hiện hết, không thu gọn. */
  readonly collapsedCount = input(0);
  readonly emptyText = input('Chưa có thay đổi nào được ghi nhận.');

  readonly expand = output<void>();

  /** Trạng thái mở tại chỗ — để component dùng được ngay cả khi caller bỏ qua `expand`. */
  private readonly expanded = signal(false);

  protected readonly visible = computed(() => {
    const all = this.entries();
    const n = this.collapsedCount();
    if (this.expanded() || n <= 0 || all.length <= n) return all;
    return all.slice(0, n);
  });

  protected readonly hiddenCount = computed(() => {
    const n = this.collapsedCount();
    if (this.expanded() || n <= 0) return 0;
    return Math.max(0, this.entries().length - n);
  });

  protected showAll(): void {
    this.expanded.set(true);
    this.expand.emit();
  }
}
